 if(!actor()||!alive()||!['guess','shuffleAsk','sage','pick'].includes(phase)){closeChoicePopup();return}
 const drawOwner=phase==='pick'?pub.target:me;
 if(['shuffleAsk','pick'].includes(phase)&&arr(players()[drawOwner]?.hand).some(c=>pendingDraws.has(c.id))){closeChoicePopup();return}
 const key=code+':'+pub.token+':'+phase;
