  for(const b of p.querySelectorAll('[data-number]')){const chosen=Number(b.dataset.number)===guess;b.classList.toggle('chosen',chosen);b.setAttribute('aria-pressed',String(chosen));b.disabled=disabled}
  const b=p.querySelector('[data-confirm]');b.textContent=`${guess} ${NAMES[guess]} で確定`;b.disabled=disabled;
