let chatLog=[],chatInitialized=false,unread=0,chatLast=0,chatSending=false,chatGeneration=0;
function resetChatUI(){chatGeneration++;chatLog=[];chatInitialized=false;unread=0;seenChat={};chatLast=0;chatSending=false;if(gameDialog.open&&gameDialog.dataset.kind==='chatHistory')gameDialog.close();renderLiveChat()}
function readChat(v){const messages=[];for(const [u,x] of Object.entries(v||{})){if(!x||typeof x!=='object')continue;const add=(id,m)=>{if(typeof m?.text==='string'&&Number.isFinite(m.at))messages.push({id:u+':'+id,u,text:m.text.slice(0,100),at:m.at})};for(const [id,m] of Object.entries(x.history||{}))add(id,m);if(!Object.values(x.history||{}).some(m=>m?.at===x.at&&m?.text===x.text))add('latest:'+x.at,x)}return messages.sort((a,b)=>a.at-b.at||a.id.localeCompare(b.id))}
