async function speak(text){text=String(text||'').trim().slice(0,100);if(!text||now()-chatLast<700||!pub||!connected||chatSending)return false;chatLast=now();chatSending=true;const gen=chatGeneration,u=me,channel=alive()?'alive':'dead',id=uid();try{const r=path(`chat/${channel}/${u}`),old=(await get(r)).val()||{};if(gen!==chatGeneration)return false;const entries=Object.entries(old.history||{}).filter(([,m])=>typeof m?.text==='string'&&Number.isFinite(m.at)).sort((a,b)=>b[1].at-a[1].at).slice(0,29);const history=Object.fromEntries(entries);if(old.text&&Number.isFinite(old.at)&&!entries.some(([,m])=>m.at===old.at&&m.text===old.text)){history['legacy-'+old.at]={text:old.text,at:old.at};if(Object.keys(history).length>29)delete history[entries.at(-1)[0]]}history[id]={text,at:serverTimestamp()};await set(r,{text,at:serverTimestamp(),history});return gen===chatGeneration}catch(e){error(e);return false}finally{if(gen===chatGeneration)chatSending=false}}
