function openChatHistory(){unread=0;const d=el('div');d.append(el('h2','','チャット履歴'),el('p','choice-note',alive()?'生存者のチャット（直近・各人最大30件）':'観戦者のチャット（直近・各人最大30件）'),el('div','chat-log'));showDialog(d,'chatHistory');renderLiveChat();const list=d.querySelector('.chat-log');list.scrollTop=list.scrollHeight}
