function renderGuessResult(){let layer=$('effectLayer'),old=layer.querySelector('.guess-result:not(.private-reveal)');if(pub.phase!=='guessResult'||pub.event?.type!=='guessResult'){old?.remove();return}let e=pub.event;if(old?.dataset.event===e.id)return;old?.remove();let f=el('div','guess-result');f.dataset.event=e.id;let v=el('div','guess-result-content');v.append(el('div','guess-intro',`${players()[e.from]?.name||'相手'} が選んだ数字は…`));let c=img(e.n,'guess-reveal-card');v.append(c,el('div',`guess-verdict ${e.hit?'hit':'miss'}`,e.hit?'的中！':'外れ…'));f.append(v);layer.append(f);let elapsed=Math.max(0,now()-e.at);let duration=prefs.short?0.55:1;for(let x of [c,v.lastChild]){let delay=(x===c?900:2050)*duration;x.style.animationDelay=`${delay-elapsed}ms`;}if(elapsed<2050*duration)setTimeout(()=>{if(f.isConnected)tone(e.hit?'end':'draw')},2050*duration-elapsed)}
