let audio=null,bgmTimer=null,step=0,musicMode='';function context(){try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();return audio}catch{return null}}document.addEventListener('pointerdown',()=>{context();music()},{once:true});function note(freq,dur,vol,type='sine',delay=0){if(!audio||!vol||audio.state!=='running')return;let o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+delay;o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,vol),t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+dur+.02)}function tone(type){let v=prefs.se/100*.10;let seq=type==='chat'?[740,990]:type==='revolution'?[130,196,261,392,523]:type==='end'?[196,247,330]:type==='shuffle'?[350,220,350]:type==='draw'?[420,600]:type==='rebirth'?[261,392,523]:[180,260];seq.forEach((f,i)=>note(f,.18,v,'triangle',i*.08))}function music(){if(!audio||!prefs.bgm||!pub){stopMusic();return}let mode=pub.phase==='lobby'?'lobby':pub.phase==='end'?(pub.reason==='革命'?'revolution':'end'):'game';if(bgmTimer&&musicMode===mode)return;stopMusic();musicMode=mode;step=0;let melodies={lobby:[196,246.94,293.66,246.94,174.61,220,261.63,220],game:[146.83,220,261.63,220,130.81,196,233.08,196,110,164.81,220,164.81,130.81,196,261.63,196],end:[261.63,329.63,392,523.25,349.23,440,523.25,392],revolution:[130.81,196,261.63,311.13,392,523.25,466.16,392]};let melody=melodies[mode];bgmTimer=setInterval(()=>{let f=melody[step++%melody.length],v=prefs.bgm/100*.045;note(f,.72,v,'sine');if(step%4===1)note(f/2,1.8,v*.7,'triangle')},680)}function stopMusic(){clearInterval(bgmTimer);bgmTimer=null}
$('settings').onclick=()=>{let d=el('div');for(let [k,t] of [['details','カード詳細表示'],['confirm','使用前の確認'],['short','演出短縮'],['history','行動履歴'],['chatSound','チャット受信通知音']]){let l=el('label'),i=el('input');i.type='checkbox';i.checked=prefs[k];i.onchange=()=>{prefs[k]=i.checked;savePrefs()};l.append(el('span','',t),i);d.append(l)}for(let [k,t] of [['bgm','BGM音量'],['se','効果音量']]){let l=el('label'),i=el('input');i.type='range';i.min=0;i.max=100;i.value=prefs[k];i.oninput=()=>{prefs[k]=+i.value;savePrefs()};l.append(el('span','',t),i);d.append(l)}d.append(btn('カード一覧',catalog));showDialog(d)};function savePrefs(){localStorage.setItem('xenoPrefs',JSON.stringify(prefs));if(!prefs.bgm)stopMusic();else music();scheduleRender()}
